import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../providers/app_state.dart';import '../dashboard/dashboard_screen.dart';import '../medicine/medicines_screen.dart';import '../appointments/appointments_screen.dart';import '../reports/reports_screen.dart';import '../settings/settings_screen.dart';
class MainShell extends ConsumerWidget{const MainShell({super.key});static const screens=[DashboardScreen(),MedicinesScreen(),AppointmentsScreen(),ReportsScreen(),SettingsScreen()];@override Widget build(BuildContext c,WidgetRef ref){final i=ref.watch(tabProvider);return Scaffold(body:screens[i],bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(v)=>ref.read(tabProvider.notifier).state=v,destinations:const [NavigationDestination(icon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.medication),label:'Meds'),NavigationDestination(icon:Icon(Icons.event),label:'Visits'),NavigationDestination(icon:Icon(Icons.description),label:'Reports'),NavigationDestination(icon:Icon(Icons.settings),label:'Settings')])) ;}}
